27	// mustSubmit 提交一个保修请求。
28	func mustSubmit(t *testing.T, s *Store, id, faultCode string) {
29		t.Helper()
30		if err := s.SubmitRequest(id, "p1", faultCode); err != nil {
31			t.Fatalf("submit request %s: %v", id, err)
32		}
