48	// assertExcludedInWindow 断言请求在保修期内被故障除外原因拒绝，且直接查询
49	// 与按请求查看的结果一致。
50	func assertExcludedInWindow(t *testing.T, s *Store, requestID string) {
51		t.Helper()
52		e, err := s.Evaluate(requestID, nowOK)
53		if err != nil {
54			t.Fatalf("evaluate %s: %v", requestID, err)
55		}
56		if e.Eligible || !e.Excluded {
57			t.Fatalf("%s: want ineligible and excluded, got %+v", requestID, e)
58		}
59		if len(e.Reasons) != 1 || e.Reasons[0] != ReasonFaultExcluded {
60			t.Fatalf("%s: reasons = %v, want only [fault_code_excluded]", requestID, e.Reasons)
61		}
62		view, err := s.RequestView(requestID, nowOK)
63		if err != nil {
64			t.Fatalf("request view %s: %v", requestID, err)
65		}
66		ve := view.Eligibility
67		if ve.Eligible != e.Eligible || ve.Excluded != e.Excluded || len(ve.Reasons) != len(e.Reasons) {
68			t.Fatalf("%s: view %+v disagrees with evaluate %+v", requestID, ve, e)
69		}
70		for i := range e.Reasons {
71			if ve.Reasons[i] != e.Reasons[i] {
72				t.Fatalf("%s: view reasons %v disagree with %v", requestID, ve.Reasons, e.Reasons)
73			}
74		}
75	}
