77	// assertEligibleInWindow 断言请求在保修期内合格、未命中除外，且直接查询
78	// 与按请求查看的结果一致。
79	func assertEligibleInWindow(t *testing.T, s *Store, requestID string) {
80		t.Helper()
81		e, err := s.Evaluate(requestID, nowOK)
82		if err != nil {
83			t.Fatalf("evaluate %s: %v", requestID, err)
84		}
85		if !e.Eligible || e.Excluded || len(e.Reasons) != 0 {
86			t.Fatalf("%s: want eligible with no reasons, got %+v", requestID, e)
87		}
88		view, err := s.RequestView(requestID, nowOK)
89		if err != nil {
90			t.Fatalf("request view %s: %v", requestID, err)
91		}
92		ve := view.Eligibility
93		if ve.Eligible != e.Eligible || ve.Excluded != e.Excluded || len(ve.Reasons) != len(e.Reasons) {
94			t.Fatalf("%s: view %+v disagrees with evaluate %+v", requestID, ve, e)
95		}
96	}
