139	// TestRetrievedProductMutationIsIsolated 取回产品资料后删除原有代码、加入
140	// 新代码：重新取回的资料、先前取得的另一份资料以及请求资格都继续反映
141	// 登记时的规则。
142	func TestRetrievedProductMutationIsIsolated(t *testing.T) {
143		s := isolationStore(t, []string{"BROKEN_SEAL"})
144		mustSubmit(t, s, "rOrig", "BROKEN_SEAL")
145		mustSubmit(t, s, "rAddedLater", "LATER_CODE")
146	
147		first, err := s.Product("p1")
148		if err != nil {
149			t.Fatalf("first product fetch: %v", err)
150		}
151		retrieved, err := s.Product("p1")
152		if err != nil {
153			t.Fatalf("second product fetch: %v", err)
154		}
155		// 调用方从返回的集合中删除原有代码，再加入一个新代码。
156		delete(retrieved.ExcludedCodes, "BROKEN_SEAL")
157		retrieved.ExcludedCodes["LATER_CODE"] = struct{}{}
158	
159		// 重新取回仍反映登记时规则。
160		again, err := s.Product("p1")
161		if err != nil {
162			t.Fatalf("re-fetch product: %v", err)
163		}
164		assertExcludedCodes(t, again, "BROKEN_SEAL")
165		// 此前已经取得的另一份资料不跟着改变。
166		assertExcludedCodes(t, first, "BROKEN_SEAL")
167		if _, leaked := first.ExcludedCodes["LATER_CODE"]; leaked {
168			t.Fatalf("earlier product copy gained added code: %+v", first.ExcludedCodes)
169		}
170	
171		// 资格不被调用方对取回资料的修改影响：原有代码仍拒绝，新代码仍合格。
172		assertExcludedInWindow(t, s, "rOrig")
173		assertEligibleInWindow(t, s, "rAddedLater")
174	}
