176	// TestEvaluateAndRequestViewStayConsistentAfterMutation 直接查询资格与按
177	// 请求查看资格时，合格标记、是否命中除外、拒绝原因必须相互一致，不能出现
178	// 资料显示已除外而请求被放行（或反之）的情况。
179	func TestEvaluateAndRequestViewStayConsistentAfterMutation(t *testing.T) {
180		s := isolationStore(t, []string{"BROKEN_SEAL", "OVERHEAT"})
181		mustSubmit(t, s, "r1", "BROKEN_SEAL")
182		mustSubmit(t, s, "r2", "OVERHEAT")
183		mustSubmit(t, s, "r3", "NOISE")
184	
185		p, _ := s.Product("p1")
186		p.ExcludedCodes["NOISE"] = struct{}{}
187		delete(p.ExcludedCodes, "BROKEN_SEAL")
188	
189		for _, id := range []string{"r1", "r2"} {
190			assertExcludedInWindow(t, s, id)
191		}
192		assertEligibleInWindow(t, s, "r3")
193	
194		// 过保时刻：原除外代码仍同时列出过保与除外两项，两种查询口径一致。
195		e, err := s.Evaluate("r1", t0.Add(31*day))
196		if err != nil {
197			t.Fatalf("evaluate after expiry: %v", err)
198		}
199		if e.Eligible || !e.Excluded || len(e.Reasons) != 2 {
200			t.Fatalf("expired+excluded: got %+v", e)
201		}
202		got := map[RejectionReason]bool{}
203		for _, r := range e.Reasons {
204			got[r] = true
205		}
206		if !got[ReasonWarrantyExpired] || !got[ReasonFaultExcluded] {
207			t.Fatalf("reasons = %v, want warranty_expired and fault_code_excluded", e.Reasons)
208		}
209		view, _ := s.RequestView("r1", t0.Add(31*day))
210		if view.Eligibility.Eligible || !view.Eligibility.Excluded ||
211			len(view.Eligibility.Reasons) != 2 {
212			t.Fatalf("view after expiry disagrees: %+v", view.Eligibility)
213		}
214	}
