1	package warranty
2	
3	import (
4		"errors"
5		"testing"
6		"time"
7	)
8	
9	// 本文件回归保障 RequestView 确认到期的范围：查询只按请求归属确认该请求自己
10	// 的承诺，同一备件被多个请求预留时不能顺带确认其他请求的承诺；同一请求的多
11	// 笔到期承诺要一次全部确认。空编号与未知请求的失败查询不确认任何承诺。
12	
13	// rvSharedStore 构造一个产品（保修 30 天）、库存为 stock 的备件和两个在保修期
14	// 内始终合格的请求，供按请求查看的到期范围测试使用。
15	func rvSharedStore(t *testing.T, stock int) *Store {
16		t.Helper()
17		s := NewStore()
18		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
19			t.Fatalf("register product: %v", err)
20		}
21		if err := s.RegisterPart("part1", stock); err != nil {
22			t.Fatalf("register part: %v", err)
23		}
24		if err := s.SubmitRequest("r1", "p1", "FAULTY"); err != nil {
25			t.Fatalf("submit r1: %v", err)
26		}
27		if err := s.SubmitRequest("r2", "p1", "FAULTY"); err != nil {
28			t.Fatalf("submit r2: %v", err)
29		}
30		return s
31	}
32	
33	// rvDetail 在请求视图中按承诺编号取明细。
34	func rvDetail(v *RequestView, id string) (CommitmentDetail, bool) {
35		for _, d := range v.Commitments {
36			if d.CommitmentID == id {
37				return d, true
38			}
39		}
40		return CommitmentDetail{}, false
41	}
42	
43	// TestRequestViewExpiryScopedToViewedRequest 对应用户给出的主例：实物库存
44	// 十件，甲预留六件并使用两件，乙预留四件，两笔承诺同一时刻到期。到期时刻
45	// 查看甲只确认甲自己：甲 expired、释放四件未用占用、已用两件不回库存；乙
46	// 不被确认。随后以到期前时刻查看，乙仍 active，备件账目为 8/4/4，甲持续
47	// expired。
48	func TestRequestViewExpiryScopedToViewedRequest(t *testing.T) {
49		s := rvSharedStore(t, 10)
50		noon := t0.Add(10 * day)
51		before := noon.Add(-time.Minute)
52	
53		// 甲预留六件并使用两件；乙预留四件，两笔承诺在同一时刻到期。
54		if _, err := s.Reserve("jia", "r1", "part1", 6, noon, before); err != nil {
55			t.Fatalf("reserve jia: %v", err)
56		}
57		if _, err := s.Use("u-jia", "jia", 2, before); err != nil {
58			t.Fatalf("use jia: %v", err)
59		}
60		if _, err := s.Reserve("yi", "r2", "part1", 4, noon, before); err != nil {
61			t.Fatalf("reserve yi: %v", err)
62		}
63	
64		// 到期时刻查看甲：明细只包含甲的承诺，状态 expired，数量仍可核对。
65		v, err := s.RequestView("r1", noon)
66		if err != nil {
67			t.Fatalf("view r1 at expiry: %v", err)
68		}
69		if !v.Eligibility.Eligible {
70			t.Fatalf("eligibility at day 10: %+v", v.Eligibility)
71		}
72		if len(v.Commitments) != 1 {
73			t.Fatalf("r1 view contains %d commitments %+v, want only jia", len(v.Commitments), v.Commitments)
74		}
75		dj := v.Commitments[0]
76		if dj.CommitmentID != "jia" || dj.Status != CommitmentExpired ||
77			dj.OriginalQuantity != 6 || dj.UsedQuantity != 2 || dj.RemainingQuantity != 4 ||
78			!dj.Expiry.Equal(noon) || dj.RequestID != "r1" || dj.PartID != "part1" {
79			t.Fatalf("jia detail: %+v, want expired 6/2/4 expiring at %v", dj, noon)
80		}
81	
82		// 甲被确认到期、乙没有被这次查询顺带确认。
83		cj, _ := s.Commitment("jia")
84		if !cj.Expired || cj.Canceled || cj.Used != 2 {
85			t.Fatalf("jia after view: %+v, want expired/used=2", cj)
86		}
87		cy, _ := s.Commitment("yi")
88		if cy.Expired || cy.Canceled || cy.Used != 0 {
89			t.Fatalf("yi confirmed by r1 view: %+v, want still unconfirmed", cy)
90		}
91	
92		// 以到期前时刻查看乙：仍 active，明细只有乙自己。
93		vy, err := s.RequestView("r2", before)
94		if err != nil {
95			t.Fatalf("view r2 before expiry: %v", err)
96		}
97		if len(vy.Commitments) != 1 {
98			t.Fatalf("r2 view contains %d commitments %+v, want only yi", len(vy.Commitments), vy.Commitments)
99		}
100		dy := vy.Commitments[0]
101		if dy.CommitmentID != "yi" || dy.Status != CommitmentActive ||
102			dy.OriginalQuantity != 4 || dy.UsedQuantity != 0 || dy.RemainingQuantity != 4 {
103			t.Fatalf("yi detail at earlier time: %+v, want active 4/0/4", dy)
104		}
105	
106		// 以到期前时刻查看备件：实物八件（甲已用两件不回库），有效占用只剩乙的
107		// 四件，可承诺四件；甲持续显示 expired。
108		st, err := s.PartStatus("part1", before)
109		if err != nil {
110			t.Fatalf("part status at earlier time: %v", err)
111		}
112		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
113			t.Fatalf("stock after scoped confirmation: phys=%d occupied=%d committable=%d, want 8/4/4",
114				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
115		}
116		pj, ok := detailByID(st, "jia")
117		if !ok || pj.Status != CommitmentExpired || pj.OriginalQuantity != 6 ||
118			pj.UsedQuantity != 2 || pj.RemainingQuantity != 4 {
119			t.Fatalf("jia in part details: %+v ok=%v, want expired 6/2/4", pj, ok)
120		}
121		py, ok := detailByID(st, "yi")
122		if !ok || py.Status != CommitmentActive || py.RemainingQuantity != 4 {
123			t.Fatalf("yi in part details: %+v ok=%v, want active remaining=4", py, ok)
124		}
125		// 甲在自己的请求视图里回退时刻也保持 expired。
126		v1, _ := s.RequestView("r1", before)
127		if d, ok := rvDetail(v1, "jia"); !ok || d.Status != CommitmentExpired {
128			t.Fatalf("jia rolled back in own view: %+v ok=%v", d, ok)
129		}
130	
131		// 乙未被确认：到期前时刻仍可使用；甲在到期前时刻也一律关闭。
132		if _, err := s.Use("u-yi", "yi", 1, before); err != nil {
133			t.Fatalf("yi closed by r1 view: %v", err)
134		}
135		if _, err := s.Use("u-jia-2", "jia", 1, before); !errors.Is(err, ErrCommitmentClosed) {
136			t.Fatalf("use jia after confirmation: got %v, want ErrCommitmentClosed", err)
137		}
138	}
139	
140	// TestRequestViewConfirmsAllOwnCommitmentsAcrossParts 保障同一请求关联多笔
141	// 承诺时确认范围按请求归属决定，不能只处理其中一笔：r1 在 partA/partB 上
142	// 各有承诺，到期的全部释放未用占用，未到期的保持有效；r2 使用相同备件、
143	// 到期时刻相同也不被确认。明细按承诺编号排序并保留原数量、已用和未用。
144	func TestRequestViewConfirmsAllOwnCommitmentsAcrossParts(t *testing.T) {
145		s := NewStore()
146		if err := s.RegisterProduct("p1", t0, 30, []string{"FAULTX"}); err != nil {
147			t.Fatalf("register product: %v", err)
148		}
149		if err := s.RegisterPart("partA", 10); err != nil {
150			t.Fatalf("register partA: %v", err)
151		}
152		if err := s.RegisterPart("partB", 10); err != nil {
153			t.Fatalf("register partB: %v", err)
154		}
155		for _, id := range []string{"r1", "r2"} {
156			if err := s.SubmitRequest(id, "p1", "FAULTY"); err != nil {
157				t.Fatalf("submit %s: %v", id, err)
158			}
159		}
160	
161		noon := t0.Add(10 * day)
162		before := noon.Add(-time.Minute)
163		later := noon.Add(day)
164	
165		// r1：partA 上一笔到期（四件用一件）、一笔尚未到期（三件）；
166		// partB 上一笔到期且已全部使用（两件）。
167		if _, err := s.Reserve("c-a1", "r1", "partA", 4, noon, before); err != nil {
168			t.Fatalf("reserve c-a1: %v", err)
169		}
170		if _, err := s.Use("u-a1", "c-a1", 1, before); err != nil {
171			t.Fatalf("use c-a1: %v", err)
172		}
173		if _, err := s.Reserve("c-a2", "r1", "partA", 3, later, before); err != nil {
174			t.Fatalf("reserve c-a2: %v", err)
175		}
176		if _, err := s.Reserve("c-b1", "r1", "partB", 2, noon, before); err != nil {
177			t.Fatalf("reserve c-b1: %v", err)
178		}
179		if _, err := s.Use("u-b1", "c-b1", 2, before); err != nil {
180			t.Fatalf("use c-b1: %v", err)
181		}
182		// r2：在相同备件上有同一时刻到期的承诺，查询 r1 不得确认它们。
183		if _, err := s.Reserve("c-a3", "r2", "partA", 2, noon, before); err != nil {
184			t.Fatalf("reserve c-a3: %v", err)
185		}
186		if _, err := s.Reserve("c-b2", "r2", "partB", 5, noon, before); err != nil {
187			t.Fatalf("reserve c-b2: %v", err)
188		}
189	
190		// 到期时刻查看 r1：三笔承诺全部出现且按编号排序，到期的两笔一次全部
191		// 确认，未到期的一笔仍 active；原数量/已用/未用都保留。
192		v, err := s.RequestView("r1", noon)
193		if err != nil {
194			t.Fatalf("view r1: %v", err)
195		}
196		wantOrder := []string{"c-a1", "c-a2", "c-b1"}
197		if len(v.Commitments) != len(wantOrder) {
198			t.Fatalf("r1 commitments = %d, want %d", len(v.Commitments), len(wantOrder))
199		}
200		for i, id := range wantOrder {
201			if v.Commitments[i].CommitmentID != id {
202				t.Fatalf("order at %d = %q, want %q (full order %v)",
203					i, v.Commitments[i].CommitmentID, id, wantOrder)
204			}
205		}
206		want := map[string]struct {
207			status                    CommitmentStatus
208			orig, used, remaining int
209			part                      string
210		}{
211			"c-a1": {CommitmentExpired, 4, 1, 3, "partA"},
212			"c-a2": {CommitmentActive, 3, 0, 3, "partA"},
213			"c-b1": {CommitmentExpired, 2, 2, 0, "partB"},
214		}
215		for _, d := range v.Commitments {
216			w := want[d.CommitmentID]
217			if d.Status != w.status || d.OriginalQuantity != w.orig ||
218				d.UsedQuantity != w.used || d.RemainingQuantity != w.remaining ||
219				d.PartID != w.part || d.RequestID != "r1" {
220				t.Fatalf("detail %s = %+v, want status=%s %d/%d/%d part=%s",
221					d.CommitmentID, d, w.status, w.orig, w.used, w.remaining, w.part)
222			}
223		}
224	
225		// r1 的到期承诺都置位，未到期承诺与 r2 的承诺都不置位。
226		for _, tc := range []struct {
227			id      string
228			expired bool
229		}{
230			{"c-a1", true}, {"c-a2", false}, {"c-b1", true},
231			{"c-a3", false}, {"c-b2", false},
232		} {
233			c, _ := s.Commitment(tc.id)
234			if c.Expired != tc.expired {
235				t.Fatalf("%s Expired=%v, want %v", tc.id, c.Expired, tc.expired)
236			}
237		}
238	
239		// partA：实物九件；c-a1 释放三件，占用只剩 c-a2 三件与 r2 的 c-a3 两件，
240		// 可承诺四件。
241		stA, err := s.PartStatus("partA", before)
242		if err != nil {
243			t.Fatalf("partA status: %v", err)
244		}
245		if stA.PhysicalRemaining != 9 || stA.ActiveOccupied != 5 || stA.Committable != 4 {
246			t.Fatalf("partA after r1 view: phys=%d occupied=%d committable=%d, want 9/5/4",
247				stA.PhysicalRemaining, stA.ActiveOccupied, stA.Committable)
248		}
249		if d, _ := detailByID(stA, "c-a1"); d.Status != CommitmentExpired || d.RemainingQuantity != 3 {
250			t.Fatalf("c-a1 in partA details: %+v, want expired remaining=3", d)
251		}
252		if d, _ := detailByID(stA, "c-a2"); d.Status != CommitmentActive || d.RemainingQuantity != 3 {
253			t.Fatalf("c-a2 in partA details: %+v, want active remaining=3", d)
254		}
255		if d, _ := detailByID(stA, "c-a3"); d.Status != CommitmentActive || d.RemainingQuantity != 2 {
256			t.Fatalf("c-a3 in partA details: %+v, want active remaining=2", d)
257		}
258	
259		// partB：实物八件；c-b1 未用为零本就不占数量，占用只剩 r2 的五件，
260		// 可承诺三件；全部用完的到期记录仍显示 expired 并保留 2/2/0。
261		stB, err := s.PartStatus("partB", before)
262		if err != nil {
263			t.Fatalf("partB status: %v", err)
264		}
265		if stB.PhysicalRemaining != 8 || stB.ActiveOccupied != 5 || stB.Committable != 3 {
266			t.Fatalf("partB after r1 view: phys=%d occupied=%d committable=%d, want 8/5/3",
267				stB.PhysicalRemaining, stB.ActiveOccupied, stB.Committable)
268		}
269		if d, _ := detailByID(stB, "c-b1"); d.Status != CommitmentExpired ||
270			d.OriginalQuantity != 2 || d.UsedQuantity != 2 || d.RemainingQuantity != 0 {
271			t.Fatalf("c-b1 in partB details: %+v, want expired 2/2/0", d)
272		}
273		if d, _ := detailByID(stB, "c-b2"); d.Status != CommitmentActive || d.RemainingQuantity != 5 {
274			t.Fatalf("c-b2 in partB details: %+v, want active remaining=5", d)
275		}
276	
277		// r2 在到期前时刻查看：两笔承诺保持原先未确认的 active 状态，按编号排序。
278		v2, err := s.RequestView("r2", before)
279		if err != nil {
280			t.Fatalf("view r2: %v", err)
281		}
282		if len(v2.Commitments) != 2 ||
283			v2.Commitments[0].CommitmentID != "c-a3" || v2.Commitments[1].CommitmentID != "c-b2" {
284			t.Fatalf("r2 commitments = %+v, want sorted [c-a3 c-b2]", v2.Commitments)
285		}
286		for _, d := range v2.Commitments {
287			if d.Status != CommitmentActive {
288				t.Fatalf("%s status = %q, want active", d.CommitmentID, d.Status)
289			}
290		}
291	
292		// 再次以较早时刻查看 r1：到期的不可逆、未到期的仍有效，状态不随时刻回退。
293		v1, err := s.RequestView("r1", before)
294		if err != nil {
295			t.Fatalf("view r1 at earlier time: %v", err)
296		}
297		if d, _ := rvDetail(v1, "c-a1"); d.Status != CommitmentExpired {
298			t.Fatalf("c-a1 rolled back: %+v", d)
299		}
300		if d, _ := rvDetail(v1, "c-b1"); d.Status != CommitmentExpired {
301			t.Fatalf("c-b1 rolled back: %+v", d)
302		}
303		if d, _ := rvDetail(v1, "c-a2"); d.Status != CommitmentActive {
304			t.Fatalf("c-a2 not active at earlier time: %+v", d)
305		}
306	
307		// r2 的承诺到期前仍可正常使用，证明未被 r1 的查询关闭。
308		if _, err := s.Use("u-b2", "c-b2", 1, before); err != nil {
309			t.Fatalf("c-b2 closed by r1 view: %v", err)
310		}
311	}
312	
313	// TestRequestViewFailuresDoNotConfirmExpiry 保障空请求编号返回
314	// ErrInvalidParam、未知请求返回 ErrNotFound，两种失败都不确认任何已有承诺
315	// 到期，也不改变库存；查询资格仍按本次传入时刻计算。
316	func TestRequestViewFailuresDoNotConfirmExpiry(t *testing.T) {
317		s := rvSharedStore(t, 10)
318		noon := t0.Add(10 * day)
319		before := noon.Add(-time.Minute)
320		if _, err := s.Reserve("jia", "r1", "part1", 6, noon, before); err != nil {
321			t.Fatalf("reserve jia: %v", err)
322		}
323		if _, err := s.Use("u-jia", "jia", 2, before); err != nil {
324			t.Fatalf("use jia: %v", err)
325		}
326	
327		// 即便传入晚于到期的时刻，提前失败的查询也不确认任何承诺。
328		if _, err := s.RequestView("", noon); !errors.Is(err, ErrInvalidParam) {
329			t.Fatalf("empty request id: got %v, want ErrInvalidParam", err)
330		}
331		if _, err := s.RequestView("rMissing", noon); !errors.Is(err, ErrNotFound) {
332			t.Fatalf("unknown request: got %v, want ErrNotFound", err)
333		}
334	
335		// 甲未被确认：到期前仍 active、占用四件未用，新使用成功。
336		v, err := s.RequestView("r1", before)
337		if err != nil {
338			t.Fatalf("view r1: %v", err)
339		}
340		d, ok := rvDetail(v, "jia")
341		if !ok || d.Status != CommitmentActive || d.OriginalQuantity != 6 ||
342			d.UsedQuantity != 2 || d.RemainingQuantity != 4 {
343			t.Fatalf("jia after failed views: %+v ok=%v, want active 6/2/4", d, ok)
344		}
345		st, _ := s.PartStatus("part1", before)
346		if st.PhysicalRemaining != 8 || st.ActiveOccupied != 4 || st.Committable != 4 {
347			t.Fatalf("stock changed by failed views: phys=%d occupied=%d committable=%d, want 8/4/4",
348				st.PhysicalRemaining, st.ActiveOccupied, st.Committable)
349		}
350		if c, _ := s.Commitment("jia"); c.Expired {
351			t.Fatalf("jia confirmed by failed view: %+v", c)
352		}
353		if _, err := s.Use("u-jia-more", "jia", 1, before); err != nil {
354			t.Fatalf("jia closed by a non-confirming failed view: %v", err)
355		}
356	}
