242		if _, err := s.Cancel("c-five", later); err != nil {
243			t.Fatalf("cancel c-five: %v", err)
244		}
245	
246		// 最新查询：实物 9、有效占用 3、可承诺 6。
247		latest, err := s.PartStatus(partIsolationPartID, later)
248		if err != nil {
