	c, _ := s.Commitment("c1")
	if c.Used != 10 || c.Unused() != 0 {
		t.Fatalf("commitment: used=%d unused=%d", c.Used, c.Unused())
	}
	st, _ := s.PartStatus("part1", nowOK)
	if st.PhysicalRemaining != 0 {
		t.Fatalf("physical remaining = %d, want 0", st.PhysicalRemaining)
	}
}

