94	// 不因为当地一天只有二十三小时或二十五小时而提前或推后；截止时刻保留购买
95	// 时刻的时区表示与小数秒精度，不取整到整秒、整点或当天零点。
96	func TestWarrantyDSTOneDayAlwaysTwentyFourHours(t *testing.T) {
97		for _, tc := range dstCases(t) {
98			t.Run(tc.name, func(t *testing.T) {
99				s := NewStore()
100				expiry := registerOneDayWarranty(t, s, tc.purchase)
101	
102				if name, off := tc.purchase.Zone(); off != tc.purchaseOff {
103					t.Fatalf("purchase offset = %s(%d), want %d", name, off, tc.purchaseOff)
104				}
105				// 实际跨度必须正好二十四小时：Unix 秒差 86400，纳秒差也为 0。
106				if got := expiry.Sub(tc.purchase); got != 24*time.Hour {
107					t.Fatalf("actual warranty length = %v, want 24h", got)
108				}
109				if got := expiry.Unix() - tc.purchase.Unix(); got != secondsPerDay {
110					t.Fatalf("actual warranty length = %d seconds, want %d", got, secondsPerDay)
111				}
112	
113				loc := nyc(t)
114				got := expiry.In(loc)
115				if got.Year() != 2026 || got.Month() != tc.expMonth || got.Day() != tc.expDay ||
116					got.Hour() != tc.expHour || got.Minute() != tc.expMinute || got.Second() != 0 {
117					t.Fatalf("expiry clock = %v, want 2026-%02d-%02d %02d:%02d:00",
118						got.Format("2006-01-02 15:04:05"), tc.expMonth, tc.expDay, tc.expHour, tc.expMinute)
119				}
120				if name, off := got.Zone(); name != tc.expZone || off != tc.expOff {
121					t.Fatalf("expiry zone = %s(%d), want %s(%d)", name, off, tc.expZone, tc.expOff)
122				}
123				// 小数秒原样保留在截止时刻。
124				if got.Nanosecond() != tc.purchase.Nanosecond() || got.Nanosecond() != 123456789 {
125					t.Fatalf("sub-second precision lost: expiry nanos = %d, purchase = %d",
126						got.Nanosecond(), tc.purchase.Nanosecond())
127				}
128	
129				e, err := s.Evaluate("r", tc.purchase)
130				if err != nil {
131					t.Fatal(err)
132				}
133				if !e.PurchaseTime.Equal(tc.purchase) || e.WarrantyDays != 1 {
134					t.Fatalf("basis = (%v, %d days), want (%v, 1)", e.PurchaseTime, e.WarrantyDays, tc.purchase)
135				}
136			})
137		}
138	}
139	
140	// alternativeZones 返回同一实际时刻的不同文字表示：纽约本地、协调世界时，
141	// 以及日期/小时完全不同的两个固定偏移（秋退截止时刻 16:00Z 在 UTC+8 已是
142	// 次日零点）。结论不得因表示不同而改变。
143	func alternativeZones(t *testing.T) []*time.Location {
144		return []*time.Location{
145			nyc(t),
146			time.UTC,
147			time.FixedZone("UTC+8", 8*3600),
148			time.FixedZone("UTC-8", -8*3600),
149		}
150	}
151	
152	func reasonsEqual(a, b []RejectionReason) bool {
153		if len(a) != len(b) {
154			return false
155		}
156		for i := range a {
157			if a[i] != b[i] {
158				return false
159			}
160		}
161		return true
162	}
163	
164	// TestWarrantyDSTEligibilityBoundaryAndZoneRepresentation 验证两种切换下：
165	// 截止前一纳秒仍合格；恰好到达截止时刻及之后过保，拒绝原因明确只有保修已
166	// 到期；同一查询时刻换协调世界时或其他时区表示，资格结果与实际截止时刻一致。
167	func TestWarrantyDSTEligibilityBoundaryAndZoneRepresentation(t *testing.T) {
168		for _, tc := range dstCases(t) {
169			t.Run(tc.name, func(t *testing.T) {
170				s := NewStore()
171				expiry := registerOneDayWarranty(t, s, tc.purchase)
172	
173				before := expiry.Add(-time.Nanosecond)
174				at := expiry
175				after := expiry.Add(time.Nanosecond)
176	
177				for _, z := range alternativeZones(t) {
178					t.Run(z.String(), func(t *testing.T) {
179						// 截止前一纳秒：合格，无拒绝原因。
180						e, err := s.Evaluate("r", before.In(z))
181						if err != nil {
182							t.Fatalf("evaluate 1ns before: %v", err)
183						}
184						if !e.Eligible || len(e.Reasons) != 0 {
185							t.Fatalf("1ns before expiry: %+v", e)
186						}
187						if !e.WarrantyExpiry.Equal(expiry) {
188							t.Fatalf("expiry instant %v drifted with query zone %s", e.WarrantyExpiry, z)
189						}
190	
191						// 恰好到达截止时刻：过保，原因明确为保修已到期。
192						eAt, err := s.Evaluate("r", at.In(z))
193						if err != nil {
194							t.Fatalf("evaluate at expiry: %v", err)
195						}
196						if eAt.Eligible || !reasonsEqual(eAt.Reasons, []RejectionReason{ReasonWarrantyExpired}) {
197							t.Fatalf("at expiry: %+v", eAt)
198						}
199						if !eAt.WarrantyExpiry.Equal(expiry) {
200							t.Fatalf("expiry instant %v drifted with query zone %s", eAt.WarrantyExpiry, z)
201						}
202	
203						// 截止之后一纳秒：同样过保。
204						eAfter, err := s.Evaluate("r", after.In(z))
205						if err != nil {
206							t.Fatalf("evaluate after expiry: %v", err)
207						}
208						if eAfter.Eligible || !reasonsEqual(eAfter.Reasons, []RejectionReason{ReasonWarrantyExpired}) {
209							t.Fatalf("after expiry: %+v", eAfter)
210						}
211						if !eAfter.WarrantyExpiry.Equal(eAt.WarrantyExpiry) {
212							t.Fatalf("expiry instants differ across query times/zones")
213						}
214					})
215				}
216	
217				// 钟面陷阱：按当地钟面小时而非实际经过时间判断就会得出错误结论。
218				e, err := s.Evaluate("r", tc.clockTrap)
219				if err != nil {
220					t.Fatal(err)
221				}
222				if e.Eligible != tc.clockTrapElig {
223					t.Fatalf("clock-face trap at %v: eligible=%v, want %v, reasons %v",
224						tc.clockTrap, e.Eligible, tc.clockTrapElig, e.Reasons)
225				}
226				if tc.clockTrapElig {
227					if len(e.Reasons) != 0 {
228						t.Fatalf("spring-forward next noon must be eligible, reasons %v", e.Reasons)
229					}
230				} else if !containsReason(e.Reasons, ReasonWarrantyExpired) {
231					t.Fatalf("fall-back 11:30 wall clock must be expired, reasons %v", e.Reasons)
232				}
233			})
234		}
235	}
236	
237	// TestWarrantyDSTReserveBoundary 验证跨夏令时的时间规则同样约束首次预留：
238	// 库存充足且承诺自身到期时刻晚于保修截止时刻时，截止前的新承诺成功；到达
239	// 保修截止时刻后（无论用哪个时区表示该时刻）的新承诺一律返回现有不合格
240	// 错误，不创建承诺、不增加占用。此前成功的承诺只按它自己的到期时刻有效，
241	// 产品刚过保不会取消它或释放其未用数量；按请求查看资格与直接查询一致，
242	// 能看到准确的截止时刻、过保原因和成功承诺明细。
243	func TestWarrantyDSTReserveBoundary(t *testing.T) {
244		for _, tc := range dstCases(t) {
245			t.Run(tc.name, func(t *testing.T) {
246				s := NewStore()
247				expiry := registerOneDayWarranty(t, s, tc.purchase)
248				if err := s.RegisterPart("sp", 5); err != nil {
249					t.Fatal(err)
250				}
251				// 承诺自身到期时刻晚于保修截止时刻，两者各自独立。
252				commitExpiry := expiry.Add(2 * time.Hour)
253	
254				// 保修截止前一纳秒：新承诺成功。
255				c1, err := s.Reserve("c1", "r", "sp", 2, commitExpiry, expiry.Add(-time.Nanosecond))
256				if err != nil {
257					t.Fatalf("reserve before warranty expiry: %v", err)
258				}
259				if c1.Quantity != 2 || c1.Used != 0 || c1.Canceled || c1.Expired ||
260					!c1.Expiry.Equal(commitExpiry) {
261					t.Fatalf("unexpected commitment: %+v", c1)
262				}
263	
264				// 到达保修截止时刻：同一实际时刻换纽约、协调世界时和 UTC+8
265				// （秋退时已是另一天的零点）三种表示，结论必须一致。
266				for i, z := range []*time.Location{nyc(t), time.UTC, time.FixedZone("UTC+8", 8*3600)} {
267					failID := fmt.Sprintf("c-fail-%d", i)
268					_, err := s.Reserve(failID, "r", "sp", 1, commitExpiry.In(z), expiry.In(z))
269					if !errors.Is(err, ErrIneligible) {
270						t.Fatalf("reserve at warranty expiry in %s: got %v, want ErrIneligible", z, err)
271					}
272					if _, err := s.Commitment(failID); !errors.Is(err, ErrNotFound) {
273						t.Fatalf("rejected reserve %s must not create a commitment, got %v", failID, err)
274					}
275				}
276	
277				// 全部失败提交都不增加占用：仍只有 c1 的 2 件。
278				st, err := s.PartStatus("sp", expiry)
279				if err != nil {
280					t.Fatal(err)
281				}
282				if st.PhysicalRemaining != 5 || st.ActiveOccupied != 2 || st.Committable != 3 {
283					t.Fatalf("stock after rejected reserves: %+v", st)
284				}
285				if len(st.Details) != 1 || st.Details[0].CommitmentID != "c1" {
286					t.Fatalf("only the successful commitment may appear, got %+v", st.Details)
287				}
288	
289				// 产品刚过保不取消 c1，也不释放其未用数量：在保修截止后、
290				// c1 自身到期前仍可按它自己的到期时刻使用。
291				afterWarranty := expiry.Add(10 * time.Minute)
292				u, err := s.Use("u1", "c1", 1, afterWarranty)
293				if err != nil {
294					t.Fatalf("successful commitment stays usable after warranty expiry: %v", err)
295				}
296				if u.Quantity != 1 {
297					t.Fatalf("usage = %+v", u)
298				}
299				st, err = s.PartStatus("sp", afterWarranty)
300				if err != nil {
301					t.Fatal(err)
302				}
303				if st.PhysicalRemaining != 4 || st.ActiveOccupied != 1 || st.Committable != 3 {
304					t.Fatalf("stock after use: %+v", st)
305				}
306	
307				// 按请求查看资格与直接资格查询一致，并保留成功承诺明细。
308				view, err := s.RequestView("r", afterWarranty)
309				if err != nil {
310					t.Fatal(err)
311				}
312				direct, err := s.Evaluate("r", afterWarranty)
313				if err != nil {
314					t.Fatal(err)
315				}
316				if view.Eligibility == nil {
317					t.Fatal("request view missing eligibility")
318				}
319				if view.Eligibility.Eligible ||
320					!reasonsEqual(view.Eligibility.Reasons, []RejectionReason{ReasonWarrantyExpired}) {
321					t.Fatalf("view eligibility: %+v", view.Eligibility)
322				}
323				if !view.Eligibility.WarrantyExpiry.Equal(direct.WarrantyExpiry) ||
324					!view.Eligibility.WarrantyExpiry.Equal(expiry) ||
325					view.Eligibility.WarrantyDays != 1 ||
326					!view.Eligibility.PurchaseTime.Equal(tc.purchase) {
327					t.Fatalf("view eligibility basis differs from direct query: %+v vs %+v",
328						view.Eligibility, direct)
329				}
330				if local := view.Eligibility.WarrantyExpiry.In(nyc(t)); local.Hour() != tc.expHour ||
331					local.Minute() != tc.expMinute || local.Nanosecond() != 123456789 {
332					t.Fatalf("view expiry not the precise local instant: %v", local)
333				}
334				if len(view.Commitments) != 1 {
335					t.Fatalf("want only c1 detail, got %+v", view.Commitments)
336				}
337				d := view.Commitments[0]
338				if d.CommitmentID != "c1" || d.OriginalQuantity != 2 || d.UsedQuantity != 1 ||
339					d.RemainingQuantity != 1 || d.Status != CommitmentActive || !d.Expiry.Equal(commitExpiry) {
340					t.Fatalf("successful commitment detail not preserved: %+v", d)
341				}
342	
343				// 截止前查看仍合格，且同样保留该承诺明细。
344				viewBefore, err := s.RequestView("r", expiry.Add(-time.Nanosecond))
345				if err != nil {
346					t.Fatal(err)
347				}
348				if !viewBefore.Eligibility.Eligible || len(viewBefore.Commitments) != 1 {
349					t.Fatalf("view before expiry: elig=%+v commitments=%+v",
350						viewBefore.Eligibility, viewBefore.Commitments)
351				}
352	
353				// c1 只按它自己的到期时刻有效：到达其自身到期时刻时新使用关闭，
354				// 与保修截止时刻无关。
355				if _, err := s.Use("u2", "c1", 1, commitExpiry); !errors.Is(err, ErrCommitmentClosed) {
356					t.Fatalf("use at commitment own expiry: got %v, want ErrCommitmentClosed", err)
357				}
358	
359				// 失败提交的历史记录保留准确资格依据快照：购买时刻、一天期限、
360				// 跨夏令时的截止时刻和保修已到期原因。
361				hist, err := s.RequestHistory("r")
362				if err != nil {
363					t.Fatal(err)
364				}
365				if len(hist) != 4 || !hist[0].Success {
366					t.Fatalf("history = %+v", hist)
367				}
368				last := hist[len(hist)-1]
369				if last.Success || last.Error != HistoryErrorIneligible || last.Eligibility == nil {
370					t.Fatalf("last history record = %+v, want ineligible failure with basis", last)
371				}
372				basis := last.Eligibility
373				if !basis.WarrantyExpiry.Equal(expiry) || basis.WarrantyDays != 1 ||
374					!basis.PurchaseTime.Equal(tc.purchase) ||
375					!containsReason(basis.Reasons, ReasonWarrantyExpired) {
376					t.Fatalf("failure eligibility basis = %+v", basis)
377				}
378			})
379		}
380	}
